def build_agent(sandbox):
    # Horizontal beam to separate small from medium/large particles
    horizontal_beam = sandbox.add_static_beam(
        x=6.05, y=1.92, width=1.7, height=0.08, angle=0, density=200.0
    )

    # Vertical beams at the edges of the feed zone to block large particles
    vertical_beam_left = sandbox.add_static_beam(
        x=5.2, y=2.085, width=0.08, height=0.73, angle=0, density=200.0
    )
    vertical_beam_right = sandbox.add_static_beam(
        x=6.9, y=2.085, width=0.08, height=0.73, angle=0, density=200.0
    )

    return [horizontal_beam, vertical_beam_left, vertical_beam_right]

